require dirname(__DIR__).'/app/bootstrap.php';require_permission('settings.view');require dirname(__DIR__).'/app/layout.php';require dirname(__DIR__).'/app/backup.php';require dirname(__DIR__).'/app/ai.php';
$tabs=['business'=>['Business profile','building'],'billing'=>['Invoice & billing','file-invoice'],'appearance'=>['Appearance','sun'],'regional'=>['Regional preferences','calendar'],'ai'=>['AI & integrations','sparkles'],'memory'=>['AI memory & history','database'],'backup'=>['Backup & restore','database'],'demo'=>['Demo data & reset','refresh'],'security'=>['Security','shield-check'],'activity'=>['Activity logs','clock'],'help'=>['Help & user manual','help-circle'],'about'=>['About & system','circle-check']];$tab=(string)($_GET['tab']??'business');if(!isset($tabs[$tab]))$tab='business';$owner=current_user()['role']==='owner';if(!$owner&&!in_array($tab,['appearance','help','about'],true))$tab='appearance';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??$tab;
 if($action==='appearance'){$theme=required_text('theme');$density=required_text('density');if(!in_array($theme,['light','dark','system'],true)||!in_array($density,['default','compact','large'],true))throw new DomainException('Choose a valid appearance preset.');$prefs=['theme'=>$theme,'density'=>$density];foreach(['primary','accent'] as $key){$color=(string)($_POST[$key]??($key==='primary'?'#0ea5e9':'#0369a1'));if(!preg_match('/^#[0-9a-f]{6}$/iD',$color))throw new DomainException('Choose a valid color.');$prefs[$key]=$color;}foreach(['font_size'=>[12,18,13],'radius'=>[0,20,10],'sidebar_width'=>[210,300,246]] as $key=>[$min,$max,$default]){$v=(int)($_POST[$key]??$default);if($v<$min||$v>$max)throw new DomainException('Appearance value outside the supported range.');$prefs[$key]=$v;}query('INSERT INTO user_preferences(user_id,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[current_user()['id'],json_encode($prefs)]);audit('preferences.updated','user',(int)current_user()['id']);}
 else {require_owner();
 if($action==='business'){$name=required_text('name',160);$data=profile();foreach(['address','email','phone','website','gstin','legal_name','industry','payment_instructions','terms'] as $k){$data[$k]=mb_substr(trim((string)($_POST[$k]??'')),0,2000);}if($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))throw new DomainException('Enter a valid business email.');$data['name']=$name;query('UPDATE businesses SET name=?,profile=? WHERE id=?',[$name,json_encode($data),bid()]);audit('business.profile_updated','business',bid());}
 elseif($action==='billing'){$terms=mb_substr((string)($_POST['terms']??''),0,2000);$profile=profile();$profile['terms']=$terms;$profile['payment_instructions']=mb_substr((string)($_POST['payment_instructions']??''),0,2000);query('UPDATE businesses SET profile=? WHERE id=?',[json_encode($profile),bid()]);audit('billing.defaults_updated','business',bid());}
 elseif($action==='backup'){create_backup();flash('Backup created and integrity signature recorded.');redirect('settings.php?tab=backup');}
 elseif($action==='restore_preview'){if(!password_verify((string)($_POST['password']??''),current_user()['password_hash']))throw new DomainException('Re-enter your current Owner password.');$file=$_FILES['backup']??null;if(!$file||$file['error']!==UPLOAD_ERR_OK||$file['size']>20*1024*1024||!is_uploaded_file($file['tmp_name']))throw new DomainException('Choose a valid backup file under 20 MB.');$raw=file_get_contents($file['tmp_name']);$data=read_backup($raw);$nonce=bin2hex(random_bytes(24));if(!is_dir($config['storage'].'/temp'))mkdir($config['storage'].'/temp',0700,true);$path=$config['storage'].'/temp/'.$nonce.'.json';file_put_contents($path,$raw);chmod($path,0600);$_SESSION['restore_preview']=['file'=>$nonce,'hash'=>hash('sha256',$raw),'expires'=>time()+600,'counts'=>array_map('count',$data['tables']),'created_at'=>$data['created_at']];flash('Backup verified. Review the replacement preview and confirm below.');redirect('settings.php?tab=backup');}
 elseif($action==='restore_confirm'){if(!password_verify((string)($_POST['password']??''),current_user()['password_hash'])||($_POST['confirmation']??'')!=='RESTORE')throw new DomainException('Enter your Owner password and type RESTORE.');$preview=$_SESSION['restore_preview']??null;if(!$preview||$preview['expires']<time()||!preg_match('/^[a-f0-9]{48}$/D',$preview['file']))throw new DomainException('Restore preview expired. Upload your backup again.');$path=$config['storage'].'/temp/'.$preview['file'].'.json';$raw=file_get_contents($path);if(!hash_equals($preview['hash'],hash('sha256',$raw)))throw new DomainException('The staged backup changed. Upload it again.');$data=read_backup($raw);restore_backup($data);unlink($path);unset($_SESSION['restore_preview']);flash('Backup restored and financial relationships validated. A recovery backup was kept.');redirect('settings.php?tab=backup');}
 elseif($action==='demo_remove'){if(!password_verify((string)($_POST['password']??''),current_user()['password_hash'])||($_POST['confirmation']??'')!=='REMOVE DEMO')throw new DomainException('Enter your Owner password and type REMOVE DEMO.');remove_demo();flash('Demo records removed. Your Owner account, settings, and non-demo data have been preserved.');redirect('dashboard.php');}
 elseif($action==='ai_save'){$name=required_text('provider_name',120);$protocol=required_text('protocol',40);if(!in_array($protocol,['openai','anthropic','gemini'],true))throw new DomainException('Choose an implemented API protocol.');$endpoint=required_text('endpoint',500);safe_endpoint($endpoint);$model=required_text('model',160);$key=required_text('api_key',400);if(preg_match('/[\r\n\x00]/',$key))throw new DomainException('API keys cannot contain control characters.');$encrypted=encrypt_key($key);transaction(function()use($name,$protocol,$endpoint,$model,$encrypted){query('UPDATE ai_provider_configs SET active=0 WHERE business_id=?',[bid()]);query('INSERT INTO ai_provider_configs(business_id,name,protocol,endpoint,model,encrypted_key,active) VALUES(?,?,?,?,?,?,1)',[bid(),$name,$protocol,$endpoint,$model,$encrypted]);audit('ai.provider_configured','ai');});}
 elseif($action==='ai_test'){$provider=one('SELECT * FROM ai_provider_configs WHERE business_id=? AND active=1 ORDER BY id DESC LIMIT 1',[bid()]);if(!$provider)throw new DomainException('Configure a provider first.');call_provider($provider,'Reply with the word connected.',['purpose'=>'Connection test; no business records supplied.']);audit('ai.connection_test','ai');flash('Connection test succeeded.');redirect('settings.php?tab=ai');}
 elseif($action==='ai_policy'){save_setting('ai_enabled',isset($_POST['enabled']));save_setting('ai_history',isset($_POST['history']));$modules=array_values(array_intersect($_POST['modules']??[],['summary','outstanding','customers','tasks']));save_setting('ai_modules',$modules);audit('ai.policy_updated','ai');}
 elseif($action==='ai_prompt'){$prompt=mb_substr((string)($_POST['prompt']??''),0,8000);transaction(function()use($prompt){save_setting('ai_prompt',$prompt);query('INSERT INTO ai_prompt_versions(business_id,user_id,content) VALUES(?,?,?)',[bid(),current_user()['id'],$prompt]);audit('ai.prompt_updated','ai');});}
 elseif($action==='ai_delete'){query('DELETE FROM ai_provider_configs WHERE business_id=?',[bid()]);save_setting('ai_enabled',false);audit('ai.credentials_removed','ai');}
 elseif($action==='memory_clear'){query('DELETE FROM ai_memory_entries WHERE business_id=?',[bid()]);audit('ai.memory_cleared','ai');}
 elseif($action==='history_clear'){transaction(function(){query('DELETE m FROM ai_messages m JOIN ai_conversations c ON c.id=m.conversation_id WHERE c.business_id=?',[bid()]);query('DELETE FROM ai_conversations WHERE business_id=?',[bid()]);audit('ai.history_cleared','ai');});}
 else throw new DomainException('Unknown settings action.');
 }
 flash('Your settings have been saved.');redirect('settings.php?tab='.urlencode($tab));
}catch(DomainException $ex){$error=$ex->getMessage();}}
page_start('Settings','Make this workspace work for you.');error_notice($error);
