<?php elseif($tab==='ai'):$providers=rows('SELECT id,name,protocol,endpoint,model,active FROM ai_provider_configs WHERE business_id=? ORDER BY id DESC',[bid()]); ?><p>Provider requests send your message and selected authorized context outside this application. Review your chosen provider’s current retention and pricing policies.</p><h3>Activation & access policy</h3><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="ai_policy"><div class="permission-grid"><label><input type="checkbox" name="enabled" <?= setting('ai_enabled',false)?'checked':'' ?>> Enable external AI</label><label><input type="checkbox" name="history" <?= setting('ai_history',true)?'checked':'' ?>> Retain conversations</label></div><h3>Allowed backend data tools</h3><div class="permission-grid"><?php foreach(['summary'=>'Financial summary','outstanding'=>'Outstanding invoices','customers'=>'Customer search','tasks'=>'Upcoming tasks'] as $k=>$label): ?><label><input type="checkbox" name="modules[]" value="<?= $k ?>" <?= in_array($k,setting('ai_modules',['summary','outstanding','customers','tasks']),true)?'checked':'' ?>><?= $label ?></label><?php endforeach; ?></div><div class="form-actions"><button class="btn primary">Save access policy</button></div></form><h3>Configured providers</h3><?php foreach($providers as $provider): ?><div class="provider-row"><strong><?= e($provider['name']) ?></strong><p class="muted"><?= e($provider['model']) ?> · <?= e($provider['protocol']) ?> · Credential: •••••••• · <?= $provider['active']?'Default':'Inactive' ?></p></div><?php endforeach;if(!$providers): ?><p class="muted">No provider connected.</p><?php endif; ?><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="ai_test"><button class="btn"><?= icon('circle-check') ?> Test default provider</button></form><h3>Add a provider / replace default</h3><form method="post" autocomplete="off"><?php csrf_field(); ?><input type="hidden" name="action" value="ai_save"><div class="form-grid"><?php field('provider_name',['Display name','text',true]);field('protocol',['Implemented protocol',['openai','anthropic','gemini']]);field('endpoint',['Full HTTPS API endpoint','url',true]);field('model',['Custom model ID','text',true]);field('api_key',['API key (encrypted on the server)','password',true]); ?></div><p class="muted">Use the full request endpoint: OpenAI/OpenRouter-compatible chat completions, Anthropic messages, or Gemini generateContent for your selected model. Custom endpoints must use one of these protocols. Internal network targets are blocked.</p><div class="form-actions"><button class="btn primary">Save encrypted provider</button></div></form><h3>Business instructions</h3><p class="muted">These instructions supplement fixed safety rules. They cannot grant permissions or execute actions.</p><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="ai_prompt"><?php field('prompt',['Additional system instructions','textarea'],setting('ai_prompt','')); ?><div class="form-actions"><button class="btn primary">Save prompt version</button></div></form><details><summary>Prompt version history</summary><?php foreach(rows('SELECT content,created_at FROM ai_prompt_versions WHERE business_id=? ORDER BY id DESC LIMIT 10',[bid()]) as $v): ?><p class="muted"><?= e($v['created_at']) ?></p><pre class="proposal-payload"><?= e($v['content']) ?></pre><?php endforeach; ?></details><form method="post" data-confirm="Remove all configured AI credentials and disable external AI?"><?php csrf_field(); ?><input type="hidden" name="action" value="ai_delete"><div class="form-actions"><button class="btn danger">Remove provider credentials</button></div></form>
